 * rebuilt as one new pile carrying the sample piece's deck metadata, and the originals go.
 */
async function gatherInto(sources, target) {
    if (sources.length === 0) {
        return false;
    }
    if (sources.length === 1 && sources[0].kind === "deck") {
        const only = sources[0];
        only.setPosition(restingPoint(target));
        await world.wait(0.2);
        if (only.faceUp === true) {
            only.flip();
            await world.wait(0.2);
        }
        only.shuffle();
        return true;
    }
    const cardIds = [];
    let template = null;
    for (const source of sources) {
        const ids = cardIdsFrom(source);
        for (const id of ids) {
            cardIds.push(id);
        }
        // Prefer a pile as the sample: it carries the deck-level art slice in full.
        if (ids.length > 0 && (!template || (template.kind !== "deck" && source.kind === "deck"))) {
            template = source;
        }
