    if (!template || cardIds.length === 0) {
        world.log("Reshuffle: nothing recognisable as cards to gather.");
        return false;
    }
    const label = template.kind === "deck" && template.name ? template.name : "Deck";
    const tags = template.tags.slice();
    const metadata = pileMetadata(template, cardIds);
    for (const source of sources) {
        source.destroy();
    }
    await world.wait(0.3);
    const rebuilt = await world.spawnObject({
        kind: "deck",
        name: label,
        position: restingPoint(target),
        metadata,
        tags
    });
    if (!rebuilt) {
        world.log("Reshuffle: could not rebuild the draw pile.");
        return false;
    }
    await world.wait(0.3);
    rebuilt.shuffle();
    return true;
}
refObject.onPressed.add(async () => {
    if (running) {
        world.log("Reshuffle: already running.");
        return;
    }
    running = true;
    try {
        const discardZone = await findZone(vars.discardZoneName);
        const deckZone = await findZone(vars.deckZoneName);
        if (!discardZone || !deckZone) {
            world.log(`Reshuffle: need zones named "${vars.discardZoneName}" and "${vars.deckZoneName}".`);
            return;
        }
        const allDecks = await world.getAllObjects({ kind: "deck" });
        const allCards = await world.getAllObjects({ kind: "card" });
        const discardPiles = allDecks.filter((deck) => insideZone(discardZone, deck.position));
        const discardCards = allCards.filter((card) => insideZone(discardZone, card.position));
        const inDiscard = discardPiles.concat(discardCards);
        if (inDiscard.length === 0) {
            world.log("Reshuffle: the discard zone is empty.");
            return;
        }
        // Highest piece wins: that is the face-up card play is currently matching against.
        let highest = inDiscard[0];
        for (const piece of inDiscard) {
            if (piece.position[1] > highest.position[1]) {
                highest = piece;
            }
        }
        // Peel the played card off the pile so it stays behind while the rest goes back.
        let keeperId = highest.id;
        if (highest.kind === "deck" && highest.stackCount > 1) {
            const peeled = await highest.drawCard();
            if (peeled) {
                keeperId = peeled.id;
                peeled.setPosition(restingPoint(discardZone));
                await world.wait(0.2);
                if (peeled.faceUp !== true) {
                    peeled.flip();
                }
            }
        }
        else if (highest.faceUp !== true) {
            highest.flip();
        }
        // Everything else in the discard zone, plus whatever is already standing in the deck
        // zone, becomes the new draw pile. Re-read each piece: the peel above changed one.
        const sources = [];
        for (const piece of inDiscard) {
            if (piece.id === keeperId) {
                continue;
            }
            const state = await piece.refresh();
            if (state) {
                sources.push(piece);
            }
        }
        for (const deck of allDecks) {
            if (deck.id !== keeperId && insideZone(deckZone, deck.position)) {
                const state = await deck.refresh();
                if (state) {
                    sources.push(deck);
                }
            }
        }
        for (const card of allCards) {
            if (card.id !== keeperId && insideZone(deckZone, card.position)) {
                const state = await card.refresh();
                if (state) {
                    sources.push(card);
                }
            }
        }
        if (sources.length === 0) {
            world.log("Reshuffle: only the played card is in the discard zone - nothing to gather.");
            return;
        }
        const gathered = await gatherInto(sources, deckZone);
        if (gathered) {
            world.broadcast("Discards reshuffled into the draw pile.");
        }
    }
    finally {
        running = false;
    }
});

scripts.source:
// OCHO - Reset button.
// Object script on the Reset button; `refObject` is that ButtonObject.
//
// One press collects every card on the table - hands, discard pile, play area,
// anywhere - rebuilds them as one face-down pile in the Deck zone, and shuffles it.
//
// Cards are gathered by DECK IDENTITY: only pieces belonging to the same deck as the
// biggest pile on the table are swept up, so a second deck or an unrelated card sitting
// out is left alone.

const vars = declareVariables({
  deckZoneName: { type: "string", label: "Deck zone name", default: "Deck" }
});

/** Keys that must NOT ride along when the pile is rebuilt from a sample piece. */
const METADATA_SKIP = [
  "cards",
  "cardId",
  "scriptId",
  "scriptVars",
  "stackCount",
  "stackModelVersion",
  "cardOverlays",
  "counters",
  "__redacted"
];

let running = false;

async function findZone(name: string): Promise<SeatZoneInfo | null> {
  const wanted = name.trim().toLowerCase();
  if (!wanted) {
    return null;
  }
  const zones = await world.getSeatZones();
  for (const zone of zones) {
    if (zone.name.trim().toLowerCase() === wanted) {
      return zone;
    }
  }
  return null;
}

/** A resting spot just inside the floor of a zone box, so the pile settles in it. */
function restingPoint(zone: SeatZoneInfo): Vec3 {
  return [zone.position[0], zone.position[1] - zone.size[1] / 2 + 0.15, zone.position[2]];
}

/**
 * Which deck a piece belongs to, as a comparable string.
 *
 * A custom deck stamps its definition id on every piece it produces (a drawn card copies
 * the whole art slice), and a catalogue-sourced pile carries its provenance instead. A
 * piece with neither reports "" and is only swept up when the sample has none either.
 */
function deckIdentity(handle: ObjectHandle): string {
  const custom = handle.metadata.customDeck;
  if (custom && typeof custom === "object") {
    const id = (custom as { definitionId?: unknown }).definitionId;
    if (typeof id === "string" && id.length > 0) {
      return `custom:${id}`;
    }
  }
  const source = handle.metadata.cardSource;
  if (source && typeof source === "object") {
    const record = source as { deckId?: unknown; id?: unknown; sourceId?: unknown };
    const id = typeof record.deckId === "string"
      ? record.deckId
      : typeof record.id === "string"
        ? record.id
        : typeof record.sourceId === "string" ? record.sourceId : null;
    if (id) {
      return `source:${id}`;
    }
  }
  const preset = handle.metadata.standardPresetId;
  return typeof preset === "string" && preset.length > 0 ? `preset:${preset}` : "";
}

/** The card ids this piece holds, in pile order. */
function cardIdsFrom(handle: ObjectHandle): string[] {
  if (handle.kind === "card") {
    const own = handle.metadata.cardId;
    return typeof own === "string" && own.length > 0 ? [own] : [];
  }
  const raw = handle.metadata.cards;
  if (!Array.isArray(raw)) {
    return [];
  }
  const ids: string[] = [];
  for (const entry of raw) {
    if (typeof entry === "string" && entry.length > 0) {
      ids.push(entry);
      continue;
    }
    if (entry && typeof entry === "object") {
      const record = entry as { cardId?: unknown; id?: unknown };
      const id = typeof record.cardId === "string"
        ? record.cardId
        : typeof record.id === "string" ? record.id : null;
      if (id) {
        ids.push(id);
      }
    }
  }
  return ids;
}

/** Metadata for the rebuilt pile: everything describing the deck's art, nothing per-piece. */
function pileMetadata(template: ObjectHandle, cardIds: string[]): Record<string, unknown> {
  const built: Record<string, unknown> = {};
  for (const key of Object.keys(template.metadata)) {
    if (METADATA_SKIP.indexOf(key) === -1) {
      built[key] = template.metadata[key];
    }
  }
  built.cards = cardIds.map((cardId) => ({ cardId, faceDown: true }));
  return built;
}

refObject.onPressed.add(async () => {
  if (running) {
    world.log("Reset: already running.");
    return;
  }
  running = true;
  try {
    const deckZone = await findZone(vars.deckZoneName);
    if (!deckZone) {
      world.log(`Reset: no zone named "${vars.deckZoneName}" in this scene.`);
      return;
    }

    const decks = await world.getAllObjects({ kind: "deck" });
    const cards = await world.getAllObjects({ kind: "card" });
    const pieces: ObjectHandle[] = (decks as ObjectHandle[]).concat(cards);
    if (pieces.length === 0) {
      world.log("Reset: there are no cards on the table.");
      return;
    }

    // The sample is the biggest pile on the table; its identity decides what gets swept up.
    let sample: ObjectHandle = pieces[0];
    for (const piece of pieces) {
      if (piece.stackCount > sample.stackCount) {
        sample = piece;
      }
    }
    const identity = deckIdentity(sample);

    const sources: ObjectHandle[] = [];
    const cardIds: string[] = [];
    let template: ObjectHandle | null = null;
    for (const piece of pieces) {
      if (deckIdentity(piece) !== identity) {
        continue;
      }
      const ids = cardIdsFrom(piece);
      if (ids.length === 0) {
        continue;
      }
      sources.push(piece);
      for (const id of ids) {
        cardIds.push(id);
      }
      // Prefer a pile as the sample piece: it carries the deck-level art slice in full.
      if (!template || (template.kind !== "deck" && piece.kind === "deck")) {
        template = piece;
      }
    }

    if (!template || cardIds.length === 0) {
      world.log("Reset: found no cards belonging to the deck.");
      return;
    }

    const label = template.kind === "deck" && template.name ? template.name : "Deck";
    const tags = template.tags.slice();
    const metadata = pileMetadata(template, cardIds);

    // Clear the table first, so nothing is left behind if the rebuild is refused, and so
    // the new pile does not land on the old one.
    for (const source of sources) {
      source.destroy();
    }
    await world.wait(0.4);

    const rebuilt = await world.spawnObject({
      kind: "deck",
      name: label,
      position: restingPoint(deckZone),
      metadata,
      tags
    });
    if (!rebuilt) {
      world.log("Reset: could not rebuild the deck.");
      return;
    }
    await world.wait(0.3);
    rebuilt.shuffle();

    world.broadcast(`Table reset - ${cardIds.length} cards shuffled back into the deck.`);
  } finally {
    running = false;
  }
});

