// OCHO - Scripted variant. Generated by docs/feature-plans/game-bots/ocho/tools/build.mjs; edit the sources, not this file.
// ============================================================================================
// OCHO - the RULES KERNEL (pure: no table API, no Math.random, plain-JSON state).
//
// A card is a CODE: colour * 15 + kind for the 60 coloured cards (colour 0 red, 1 yellow, 2 blue,
// 3 green; kind 0-11 = the numbers 1-12, 12 Skip, 13 Turn, 14 Draw 2), 60 Wild, 61 Color Crush.
// A hand is a count per code. Two of each coloured card, eight Wilds, four Color Crush: 132.
//
// A match is played to OC_TARGET points (300): rounds are dealt one after another from a seeded
// generator kept in the state, so a reshuffle of the play pile is part of the replay too.
//
// Rulings where the printed rules leave room (see README.md "Rulings"):
//   - Drawing is always allowed, even holding a playable card ("cannot or do not want to play").
//   - A drawn card that can be played may be played at once (only that card) or kept (Pass).
//     A drawn card that cannot be played ends the turn by itself.
//   - Penalty draws (Draw 2, Color Crush, a caught OCHO) need no decision: they are resolved in
//     the move that caused them, one card at a time from the draw pile, and an 8 met during a
//     Draw 2 / Color Crush penalty is played at once (the OCHO Escape).
//   - The OCHO call is two moves anyone may make while a player sits on one uncalled card:
//     CALL (that player says OCHO) and CATCH (someone else does; that player draws two). The
//     chance closes when the player to move makes any other move.
//   - A round's final card ends the round at once: a Draw 2 / Color Crush going out sets no penalty.
//   - The first player of round r sits r seats after `setup.first` (the deal passes to the left),
//     and every round starts clockwise.
//   - Safety nets: a round still running after OC_ROUND_PLIES moves is void (no points, the next
//     round is dealt); after OC_MAX_ROUNDS rounds the match ends on the scores so far.
// ============================================================================================

const OC_COLORS = 4;
const OC_KINDS = 15;
const OC_SKIP = 12;
const OC_TURN = 13;
const OC_DRAW2 = 14;
const OC_WILD = 60;
const OC_CRUSH = 61;
const OC_CODES = 62;
/** Kind index of the 8s (the number 8). */
const OC_EIGHT = 7;
const OC_HAND = 7;
const OC_TARGET = 300;
const OC_MAX_SEATS = 6;
/** Move numbers (= policy slots). */
const OC_M_WILD = 60; // + colour: play a Wild and name that colour
const OC_M_CRUSH = 64; // + colour: play a Color Crush and name that colour
const OC_M_DRAW = 68;
const OC_M_PASS = 69;
const OC_M_CALL = 70; // + seat: that seat says OCHO
const OC_M_CATCH = 76; // + seat: that seat is caught without having said OCHO
const OC_POLICY = 82;
const OC_PH_PLAY = 0;
const OC_PH_DRAWN = 1;
const OC_PH_OVER = 2;
const OC_ROUND_PLIES = 1000;
const OC_MAX_ROUNDS = 60;
/** Encoding: OC_PLANES planes of 5 x 15 (a row per colour plus one for Wild / Color Crush, a column per kind). */
const OC_PLANES = 26;
const OC_ROWS = 5;

/** What the last move did, for the table's log and animation. */
interface OcLast {
  /** Seat index that moved (for CALL / CATCH: the seat called or caught). */
  p: number;
  /** "play" | "draw" | "pass" | "call" | "catch" | "void". */
  k: string;
  /** The card played or drawn (-1 when none or hidden). */
  c: number;
  /** The colour named for a Wild / Color Crush (-1 otherwise). */
  col: number;
  /** A drawn card was played straight away. */
  drawPlay: boolean;
  /** Seat that lost its turn (Skip, Draw 2, Color Crush), or -1. */
  skipped: number;
  /** Penalty: the seat that drew, how many cards (the 8 not counted) and the 8 it escaped with (-1 none). */
  penSeat: number;
  penDrew: number;
  esc: number;
  /** The play pile was turned into a new draw pile during this move. */
  reshuffled: boolean;
  /** Seat that won the round with this move (-1 none), the points it scored. */
  roundWin: number;
  points: number;
}

interface OcState {
  seats: string[];
  /** Per seat: how many of each card code are in the hand. */
  hand: number[][];
  /** The draw pile; the LAST element is the next card drawn. */
  draw: number[];
  /** The play pile, oldest first; the last element is the upcard. */
  pile: number[];
  /** The active colour (0-3). */
  color: number;
  /** +1 clockwise (seat order), -1 the other way. */
  dir: number;
  who: number;
  ph: number;
  /** The card drawn this turn (only in OC_PH_DRAWN), else -1. */
  drawn: number;
  /** Per seat: 1 while it sits on one card without having said OCHO (can still call or be caught). */
  exp: number[];
  score: number[];
  /** Round number, from 0. */
  round: number;
  /** Seat that starts the current round. */
  starter: number;
  /** The setup's first seat (round 0). */
  first: number;
  target: number;
  /** The generator's state (reshuffles, new rounds). */
  rng: number;
  ply: number;
  /** Moves in this round. */
  rply: number;
  /** -1 while the match is on, else the seat with the highest score (-2 a tie for first). */
  win: number;
  last: OcLast | null;
}

/** The match setup the table passes to `match.start`. */
interface OcSetup {
  seed: number;
  /** Seat index (into the seats list) that plays first in round 0. */
  first?: number;
  /** Points that end the match (default 300). */
  target?: number;
}

// ---------------------------------------------------------------------------- card helpers --

function ocColorOf(c: number): number {
  return c < OC_WILD ? Math.floor(c / OC_KINDS) : -1;
}

function ocKindOf(c: number): number {
  return c < OC_WILD ? c % OC_KINDS : -1;
}

function ocIsNumber(c: number): boolean {
  return c < OC_WILD && c % OC_KINDS < 12;
}

/** Points a card left in a hand is worth to the round's winner. */
function ocPoints(c: number): number {
  if (c === OC_CRUSH) return 50;
  if (c === OC_WILD) return 40;
  const k = c % OC_KINDS;
  if (k === OC_DRAW2) return 25;
  if (k >= OC_SKIP) return 20;
  return k + 1;
}

function ocHandPoints(h: number[]): number {
  let n = 0;
  for (let c = 0; c < OC_CODES; c += 1) if (h[c] > 0) n += h[c] * ocPoints(c);
  return n;
}

function ocHandSize(h: number[]): number {
  let n = 0;
  for (let c = 0; c < OC_CODES; c += 1) n += h[c];
  return n;
}

/** May card `c` go on the pile now? Wild and Color Crush always may. */
function ocCanPlay(s: OcState, c: number): boolean {
  if (c >= OC_WILD) return true;
  if (ocColorOf(c) === s.color) return true;
  const upcard = s.pile[s.pile.length - 1];
  if (upcard === undefined || upcard >= OC_WILD) return false;
  return ocKindOf(upcard) === ocKindOf(c);
}

// ---------------------------------------------------------------------------- generator --

/** One step of mulberry32 on `s.rng`: a number in [0, 1). The state carries the generator. */
function ocNext(s: OcState): number {
  s.rng = (s.rng + 0x6d2b79f5) >>> 0;
  let t = s.rng;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

function ocShuffle(s: OcState, a: number[]): void {
  for (let i = a.length - 1; i > 0; i -= 1) {
    const j = Math.floor(ocNext(s) * (i + 1));
    const t = a[i];
    a[i] = a[j];
    a[j] = t;
  }
}

function ocZeros(n: number): number[] {
  const a: number[] = [];
  for (let i = 0; i < n; i += 1) a.push(0);
  return a;
}

function ocFullDeck(): number[] {
  const cards: number[] = [];
  for (let c = 0; c < OC_WILD; c += 1) cards.push(c, c);
  for (let i = 0; i < 8; i += 1) cards.push(OC_WILD);
  for (let i = 0; i < 4; i += 1) cards.push(OC_CRUSH);
  return cards;
}

function ocClone(s: OcState): OcState {
  return {
    seats: s.seats.slice(),
    hand: s.hand.map((h) => h.slice()),
    draw: s.draw.slice(),
    pile: s.pile.slice(),
    color: s.color,
    dir: s.dir,
    who: s.who,
    ph: s.ph,
    drawn: s.drawn,
    exp: s.exp.slice(),
    score: s.score.slice(),
    round: s.round,
    starter: s.starter,
    first: s.first,
    target: s.target,
    rng: s.rng,
    ply: s.ply,
    rply: s.rply,
    win: s.win,
    last: s.last ? { ...s.last } : null
  };
}

function ocSeat(s: OcState, from: number, steps: number): number {
  const n = s.seats.length;
  return (((from + steps * s.dir) % n) + n) % n;
}

// ---------------------------------------------------------------------------- dealing --

/** Shuffle everything, deal seven each from the round's starter, turn a number card to start the pile. */
function ocDealRound(s: OcState): void {
  const n = s.seats.length;
  s.draw = ocFullDeck();
  ocShuffle(s, s.draw);
  s.pile = [];
  s.hand = [];
  for (let p = 0; p < n; p += 1) s.hand.push(ocZeros(OC_CODES));
  s.starter = (s.first + s.round) % n;
  for (let k = 0; k < OC_HAND; k += 1) {
    for (let i = 0; i < n; i += 1) {
      const c = s.draw.pop();
      if (c !== undefined) s.hand[(s.starter + i) % n][c] += 1;
    }
  }
  // The first card must be a number card: anything else goes back, the pile is shuffled, try again.
  for (;;) {
    const c = s.draw.pop() as number;
    if (ocIsNumber(c)) {
      s.pile.push(c);
      s.color = ocColorOf(c);
      break;
    }
    s.draw.push(c);
    ocShuffle(s, s.draw);
  }
  s.dir = 1;
  s.who = s.starter;
  s.ph = OC_PH_PLAY;
  s.drawn = -1;
  s.exp = ocZeros(n);
  s.rply = 0;
}

function ocInitial(seats: string[], setup?: unknown): OcState {
  const n = seats.length;
  const su = (setup && typeof setup === "object" ? setup : {}) as Partial<OcSetup>;
  const seed = typeof su.seed === "number" && isFinite(su.seed) ? Math.floor(su.seed) : 1;
  const first = typeof su.first === "number" && su.first >= 0 && su.first < n ? Math.floor(su.first) : 0;
  const target = typeof su.target === "number" && su.target >= 1 && su.target <= 5000 ? Math.floor(su.target) : OC_TARGET;
  const s: OcState = {
    seats: seats.slice(),
    hand: [],
    draw: [],
    pile: [],
    color: 0,
    dir: 1,
    who: first,
    ph: OC_PH_PLAY,
    drawn: -1,
    exp: ocZeros(n),
    score: ocZeros(n),
    round: 0,
    starter: first,
    first,
    target,
    rng: seed >>> 0,
    ply: 0,
    rply: 0,
    win: -1,
    last: null
  };
  ocDealRound(s);
  return s;
}

/**
 * The next card off the draw pile; when it is empty the play pile (all but its upcard) is
 * shuffled into a new one. -1 when there is nothing left to draw at all.
 */
function ocDrawOne(s: OcState, last: OcLast): number {
  if (s.draw.length === 0 && s.pile.length > 1) {
    const upcard = s.pile.pop() as number;
    s.draw = s.pile;
    s.pile = [upcard];
    ocShuffle(s, s.draw);
    last.reshuffled = true;
  }
  const c = s.draw.pop();
  return c === undefined ? -1 : c;
}

function ocCanDraw(s: OcState): boolean {
  return s.draw.length > 0 || s.pile.length > 1;
}

// ---------------------------------------------------------------------------- moves --

function ocCurrentPlayer(s: OcState): string {
  return s.seats[s.who];
}

function ocLegalMoves(s: OcState): number[] {
  const out: number[] = [];
  if (s.ph === OC_PH_OVER) return out;
  const p = s.who;
  const h = s.hand[p];
  if (s.ph === OC_PH_DRAWN) {
    const c = s.drawn;
    if (c === OC_WILD) for (let k = 0; k < OC_COLORS; k += 1) out.push(OC_M_WILD + k);
    else if (c === OC_CRUSH) for (let k = 0; k < OC_COLORS; k += 1) out.push(OC_M_CRUSH + k);
    else if (c >= 0 && ocCanPlay(s, c)) out.push(c);
    out.push(OC_M_PASS);
    return out;
  }
  for (let c = 0; c < OC_WILD; c += 1) if (h[c] > 0 && ocCanPlay(s, c)) out.push(c);
  if (h[OC_WILD] > 0) for (let k = 0; k < OC_COLORS; k += 1) out.push(OC_M_WILD + k);
  if (h[OC_CRUSH] > 0) for (let k = 0; k < OC_COLORS; k += 1) out.push(OC_M_CRUSH + k);
  if (ocCanDraw(s)) out.push(OC_M_DRAW);
  else out.push(OC_M_PASS);
  for (let q = 0; q < s.seats.length; q += 1) if (s.exp[q]) out.push(OC_M_CALL + q, OC_M_CATCH + q);
  return out;
}

function ocNewLast(p: number, k: string): OcLast {
  return { p, k, c: -1, col: -1, drawPlay: false, skipped: -1, penSeat: -1, penDrew: 0, esc: -1, reshuffled: false, roundWin: -1, points: 0 };
}

/** End the turn of `p`: the next seat in the current direction moves. */
function ocPassTurn(s: OcState, p: number): void {
  s.who = ocSeat(s, p, 1);
  s.ph = OC_PH_PLAY;
  s.drawn = -1;
}

/**
 * Seat `q` draws up to `n` cards, one at a time, for a Draw 2 / Color Crush. An 8 ends the draw
 * and is played straight onto the pile (the OCHO Escape): its colour becomes the active colour.
 */
function ocPenalty(s: OcState, q: number, n: number, last: OcLast): void {
  last.penSeat = q;
  for (let i = 0; i < n; i += 1) {
    const c = ocDrawOne(s, last);
    if (c < 0) break;
    if (ocKindOf(c) === OC_EIGHT) {
      s.pile.push(c);
      s.color = ocColorOf(c);
      last.esc = c;
      // Playing the 8 can leave the penalised player on one card: the OCHO call applies to it too.
      if (ocHandSize(s.hand[q]) === 1) s.exp[q] = 1;
      return;
    }
    s.hand[q][c] += 1;
    last.penDrew += 1;
  }
}

/** Score a won round; deal the next one, or end the match. */
function ocEndRound(s: OcState, p: number, last: OcLast): void {
  let pts = 0;
  for (let q = 0; q < s.seats.length; q += 1) if (q !== p) pts += ocHandPoints(s.hand[q]);
  s.score[p] += pts;
  last.roundWin = p;
  last.points = pts;
  ocNextRoundOrOver(s);
}

function ocNextRoundOrOver(s: OcState): void {
  s.round += 1;
  let best = -1;
  for (let q = 0; q < s.seats.length; q += 1) best = Math.max(best, s.score[q]);
  if (best >= s.target || s.round >= OC_MAX_ROUNDS) {
    const leaders: number[] = [];
    for (let q = 0; q < s.seats.length; q += 1) if (s.score[q] === best) leaders.push(q);
    s.win = leaders.length === 1 ? leaders[0] : -2;
    s.ph = OC_PH_OVER;
    s.exp = ocZeros(s.seats.length);
    s.drawn = -1;
    return;
  }
  ocDealRound(s);
}

/** Card `c` (already taken out of `p`'s hand) goes on the pile; `col` names the colour for a Wild / Color Crush. */
function ocResolvePlay(s: OcState, p: number, c: number, col: number, last: OcLast): void {
  s.pile.push(c);
  last.c = c;
  if (c >= OC_WILD) {
    s.color = col;
    last.col = col;
  } else s.color = ocColorOf(c);
  const left = ocHandSize(s.hand[p]);
  if (left === 0) {
    ocEndRound(s, p, last);
    return;
  }
  if (left === 1) s.exp[p] = 1;
  const n = s.seats.length;
  const k = ocKindOf(c);
  if (k === OC_SKIP) {
    last.skipped = ocSeat(s, p, 1);
    s.who = ocSeat(s, p, 2);
  } else if (k === OC_TURN) {
    if (n === 2) {
      last.skipped = ocSeat(s, p, 1);
      s.who = p;
    } else {
      s.dir = -s.dir;
      s.who = ocSeat(s, p, 1);
    }
  } else if (k === OC_DRAW2 || c === OC_CRUSH) {
    const q = ocSeat(s, p, 1);
    last.skipped = q;
    ocPenalty(s, q, c === OC_CRUSH ? 4 : 2, last);
    s.who = ocSeat(s, q, 1);
  } else s.who = ocSeat(s, p, 1);
  s.ph = OC_PH_PLAY;
  s.drawn = -1;
}

function ocApply(s0: OcState, m: number): OcState {
  const s = ocClone(s0);
  if (s.ph === OC_PH_OVER) return s;
  s.ply += 1;
  s.rply += 1;
  const p = s.who;
  const n = s.seats.length;
  // Saying OCHO, or being caught: the chance stays open for everyone else; the turn does not move.
  if (m >= OC_M_CALL && m < OC_M_CALL + OC_MAX_SEATS) {
    const q = m - OC_M_CALL;
    if (q >= n || !s.exp[q] || s.ph !== OC_PH_PLAY) throw new Error("OCHO: nobody to call OCHO for: " + m);
    s.exp[q] = 0;
    s.last = ocNewLast(q, "call");
    return s;
  }
  if (m >= OC_M_CATCH && m < OC_M_CATCH + OC_MAX_SEATS) {
    const q = m - OC_M_CATCH;
    if (q >= n || !s.exp[q] || s.ph !== OC_PH_PLAY) throw new Error("OCHO: nobody to catch: " + m);
    s.exp[q] = 0;
    const last = ocNewLast(q, "catch");
    last.penSeat = q;
    // Two cards, no OCHO Escape.
    for (let i = 0; i < 2; i += 1) {
      const c = ocDrawOne(s, last);
      if (c < 0) break;
      s.hand[q][c] += 1;
      last.penDrew += 1;
    }
    s.last = last;
    return s;
  }
  // Any other move begins the mover's turn: every OCHO chance closes.
  if (s.ph === OC_PH_PLAY) s.exp = ocZeros(n);
  const h = s.hand[p];
  if (m === OC_M_DRAW) {
    if (s.ph !== OC_PH_PLAY) throw new Error("OCHO: you have already drawn this turn");
    const last = ocNewLast(p, "draw");
    const c = ocDrawOne(s, last);
    if (c < 0) throw new Error("OCHO: nothing left to draw");
    h[c] += 1;
    last.c = c;
    s.last = last;
    if (ocCanPlay(s, c)) {
      s.ph = OC_PH_DRAWN;
      s.drawn = c;
    } else ocPassTurn(s, p);
  } else if (m === OC_M_PASS) {
    if (s.ph === OC_PH_PLAY && ocCanDraw(s)) throw new Error("OCHO: draw a card instead of passing");
    s.last = ocNewLast(p, "pass");
    ocPassTurn(s, p);
  } else {
    let c = -1;
    let col = -1;
    if (m >= 0 && m < OC_WILD) c = m;
    else if (m >= OC_M_WILD && m < OC_M_WILD + OC_COLORS) {
      c = OC_WILD;
      col = m - OC_M_WILD;
    } else if (m >= OC_M_CRUSH && m < OC_M_CRUSH + OC_COLORS) {
      c = OC_CRUSH;
      col = m - OC_M_CRUSH;
    } else throw new Error("OCHO: unknown move " + m);
    if (h[c] <= 0) throw new Error("OCHO: that card is not in the hand: " + m);
    if (s.ph === OC_PH_DRAWN && c !== s.drawn) throw new Error("OCHO: after drawing, only the drawn card may be played: " + m);
    if (!ocCanPlay(s, c)) throw new Error("OCHO: that card does not match the pile: " + m);
    const last = ocNewLast(p, "play");
    last.drawPlay = s.ph === OC_PH_DRAWN;
    h[c] -= 1;
    ocResolvePlay(s, p, c, col, last);
    s.last = last;
  }
  if (s.ph !== OC_PH_OVER && s.rply >= OC_ROUND_PLIES) {
    const last = ocNewLast(s.who, "void");
    ocNextRoundOrOver(s);
    s.last = last;
  }
  return s;
}

function ocTerminal(s: OcState): { value: Record<string, number> } | null {
  if (s.ph !== OC_PH_OVER) return null;
  const value: Record<string, number> = {};
  const n = s.seats.length;
  for (let p = 0; p < n; p += 1) value[s.seats[p]] = ocRankValue(s, p);
  return { value };
}

/** A seat's final result from its place on the scores: 1 for the best, -1 for the worst, ties equal. */
function ocRankValue(s: OcState, p: number): number {
  const n = s.seats.length;
  let ahead = 0;
  for (let q = 0; q < n; q += 1) if (s.score[q] > s.score[p]) ahead += 1;
  return n <= 1 ? 0 : 1 - (2 * ahead) / (n - 1);
}

/** Every seat's place (1 = best; equal scores share a place): the result the table reports. */
function ocRanks(s: OcState): number[] {
  const n = s.seats.length;
  const out: number[] = [];
  for (let p = 0; p < n; p += 1) {
    let ahead = 0;
    for (let q = 0; q < n; q += 1) if (s.score[q] > s.score[p]) ahead += 1;
    out.push(ahead + 1);
  }
  return out;
}

// ---------------------------------------------------------------------------- encoding --

/**
 * The position as the player to move sees it: OC_PLANES planes of 5 x 15. Rows 0-3 are the
 * colours, row 4 holds Wild (column 0) and Color Crush (column 1); a column is a card kind.
 * Opponents appear only as hand sizes and scores, relative to the mover; the draw pile only as a
 * size, so every determinization of a position encodes the same.
 */
function ocEncode(s: OcState): Float32Array {
  const W = OC_KINDS;
  const H = OC_ROWS;
  const out = new Float32Array(OC_PLANES * H * W);
  const p = s.who;
  const n = s.seats.length;
  const at = (c: number): number => (c >= OC_WILD ? 4 * W + (c - OC_WILD) : ocColorOf(c) * W + ocKindOf(c));
  const copies = (c: number): number => (c === OC_WILD ? 8 : c === OC_CRUSH ? 4 : 2);
  const cell = (plane: number, i: number, v: number): void => {
    out[plane * H * W + i] = v;
  };
  const fill = (plane: number, v: number): void => {
    for (let i = 0; i < H * W; i += 1) out[plane * H * W + i] = v;
  };
  const seen = ocZeros(OC_CODES);
  for (let i = 0; i < s.pile.length; i += 1) seen[s.pile[i]] += 1;
  for (let c = 0; c < OC_CODES; c += 1) {
    if (s.hand[p][c] > 0) cell(0, at(c), Math.min(1, s.hand[p][c] / copies(c)));
    if (seen[c] > 0) cell(4, at(c), Math.min(1, seen[c] / copies(c)));
  }
  const upcard = s.pile[s.pile.length - 1];
  if (upcard !== undefined) cell(1, at(upcard), 1);
  for (let k = 0; k < W; k += 1) cell(2, s.color * W + k, 1);
  const legal = ocLegalMoves(s);
  for (let i = 0; i < legal.length; i += 1) {
    const m = legal[i];
    if (m < OC_WILD) cell(3, at(m), 1);
    else if (m >= OC_M_WILD && m < OC_M_WILD + OC_COLORS) cell(3, at(OC_WILD), 1);
    else if (m >= OC_M_CRUSH && m < OC_M_CRUSH + OC_COLORS) cell(3, at(OC_CRUSH), 1);
  }
  if (s.ph === OC_PH_DRAWN && s.drawn >= 0) cell(5, at(s.drawn), 1);
  fill(6, s.dir > 0 ? 1 : 0);
  fill(7, s.ph === OC_PH_DRAWN ? 1 : 0);
  for (let r = 1; r < OC_MAX_SEATS; r += 1) {
    if (r >= n) continue;
    const q = ocSeat(s, p, r);
    fill(7 + r, Math.min(1, ocHandSize(s.hand[q]) / 20));
    fill(12 + r, Math.min(1, s.score[q] / s.target));
  }
  fill(18, Math.min(1, s.score[p] / s.target));
  fill(19, n / OC_MAX_SEATS);
  fill(20, Math.min(1, s.draw.length / 100));
  let others = 0;
  for (let q = 0; q < n; q += 1) if (q !== p && s.exp[q]) others = 1;
  fill(21, others);
  fill(22, s.exp[p] ? 1 : 0);
  fill(23, Math.min(1, ocHandSize(s.hand[p]) / 20));
  fill(24, Math.min(1, ocHandSize(s.hand[ocSeat(s, p, 1)]) / 7));
  fill(25, Math.min(1, s.rply / 200));
  return out;
}

/** A rough estimate for the player to move: fewer, cheaper cards than the closest rival is good. */
function ocHeuristic(s: OcState): number {
  const p = s.who;
  const mine = ocHandSize(s.hand[p]) + ocHandPoints(s.hand[p]) / 40;
  let best = Infinity;
  for (let q = 0; q < s.seats.length; q += 1) if (q !== p) best = Math.min(best, ocHandSize(s.hand[q]) + ocHandPoints(s.hand[q]) / 40);
  if (!isFinite(best)) return 0;
  const x = Math.max(-10, Math.min(10, (best - mine) / 4));
  const e = Math.exp(2 * x);
  return (e - 1) / (e + 1);
}

/**
 * A copy of `s` with everything `seat` cannot see dealt again at random: the other players' hands
 * (their sizes kept), the order of the draw pile, and the generator (future reshuffles and deals).
 */
function ocDeterminize(s0: OcState, seat: number, random: () => number): OcState {
  const s = ocClone(s0);
  const n = s.seats.length;
  const pool: number[] = [];
  const sizes: number[] = [];
  for (let q = 0; q < n; q += 1) {
    if (q === seat) {
      sizes.push(0);
      continue;
    }
    sizes.push(ocHandSize(s.hand[q]));
    for (let c = 0; c < OC_CODES; c += 1) for (let i = 0; i < s.hand[q][c]; i += 1) pool.push(c);
    s.hand[q] = ocZeros(OC_CODES);
  }
  for (let i = 0; i < s.draw.length; i += 1) pool.push(s.draw[i]);
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    const t = pool[i];
    pool[i] = pool[j];
    pool[j] = t;
  }
  let k = 0;
  for (let q = 0; q < n; q += 1) for (let i = 0; i < sizes[q]; i += 1) s.hand[q][pool[k++]] += 1;
  for (let i = 0; i < s.draw.length; i += 1) s.draw[i] = pool[k++];
  s.rng = Math.floor(random() * 4294967296) >>> 0;
  return s;
}

const kernel: RulesKernel<OcState, number> & { determinize(s: OcState, seat: string, random: () => number): OcState } = {
  id: "ocho",
  version: 1,
  initial: (seats, setup) => ocInitial(seats, setup),
  currentPlayer: (s) => ocCurrentPlayer(s),
  legalMoves: (s) => ocLegalMoves(s),
  apply: (s, m) => ocApply(s, m),
  terminal: (s) => ocTerminal(s),
  encode: (s) => ocEncode(s),
  encoding: { planes: OC_PLANES, height: OC_ROWS, width: OC_KINDS },
  policySize: OC_POLICY,
  moveIndex: (m) => m,
  moveAt: (i) => i,
  heuristic: (s) => ocHeuristic(s),
  determinize: (s, seat, random) => ocDeterminize(s, Math.max(0, s.seats.indexOf(seat)), random)
};

// ------------------------------------------------------------------------- reference bots --

/** The colour `p` holds the most points of (ties: the lowest colour), for naming after a Wild. */
function ocBestColor(s: OcState, p: number, skip: number): number {
  let best = 0;
  let bestN = -1;
  for (let k = 0; k < OC_COLORS; k += 1) {
    let v = 0;
    for (let i = 0; i < OC_KINDS; i += 1) {
      const c = k * OC_KINDS + i;
      if (c === skip) v += Math.max(0, s.hand[p][c] - 1) * (10 + ocPoints(c));
      else v += s.hand[p][c] * (10 + ocPoints(c));
    }
    if (v > bestN) {
      bestN = v;
      best = k;
    }
  }
  return best;
}

/**
 * A plain strategy: say OCHO, never pass up a play, lead with expensive cards of the colour you
 * hold most, hit a rival who is nearly out with a Skip / Turn / Draw 2, keep Wilds and Color
 * Crush for when nothing else fits (or to stop someone going out), and play a drawn card that fits.
 */
function ocGreedyMove(s: OcState): number {
  const legal = ocLegalMoves(s);
  if (legal.length === 1) return legal[0];
  const p = s.who;
  for (const m of legal) if (m >= OC_M_CALL && m < OC_M_CALL + OC_MAX_SEATS && m - OC_M_CALL === p) return m;
  const n = s.seats.length;
  const next = ocSeat(s, p, 1);
  const danger = ocHandSize(s.hand[next]) <= 2;
  let best = -1;
  let bestKey = -Infinity;
  for (const m of legal) {
    if (m === OC_M_DRAW || m === OC_M_PASS || m >= OC_M_CALL) continue;
    let c = m;
    let col = -1;
    if (m >= OC_M_WILD && m < OC_M_WILD + OC_COLORS) {
      c = OC_WILD;
      col = m - OC_M_WILD;
    } else if (m >= OC_M_CRUSH && m < OC_M_CRUSH + OC_COLORS) {
      c = OC_CRUSH;
      col = m - OC_M_CRUSH;
    }
    let key: number;
    if (c >= OC_WILD) {
      if (col !== ocBestColor(s, p, -1)) continue;
      key = danger && c === OC_CRUSH ? 300 : danger ? 5 : -100 + (c === OC_CRUSH ? 1 : 0);
    } else {
      const k = ocKindOf(c);
      const sameColor = ocColorOf(c) === s.color ? 1 : 0;
      key = ocPoints(c) + 8 * sameColor;
      // After the play, the colour should be one we hold.
      let hold = 0;
      for (let i = 0; i < OC_KINDS; i += 1) hold += s.hand[p][ocColorOf(c) * OC_KINDS + i];
      key += 3 * hold;
      if (danger && (k === OC_DRAW2 || k === OC_SKIP || (k === OC_TURN && n <= 3))) key += 200;
    }
    if (key > bestKey) {
      bestKey = key;
      best = m;
    }
  }
  if (best >= 0) return best;
  if (legal.indexOf(OC_M_DRAW) >= 0) return OC_M_DRAW;
  return legal.indexOf(OC_M_PASS) >= 0 ? OC_M_PASS : legal[0];
}

/** A playout policy for searches: greedy, and everyone always says OCHO in time. */
function ocPlayoutMove(s: OcState): number {
  for (let q = 0; q < s.seats.length; q += 1) if (s.exp[q]) return OC_M_CALL + q;
  return ocGreedyMove(s);
}

/** Moves a playout may run before it is scored on the hands instead. */
const OC_PLAYOUT_PLIES = 400;
/** Head start per world the greedy move gets in a PIMC comparison (measured: see README). */
const OC_PIMC_PRIOR = 0.15;

/** What a finished (or cut-off) playout is worth to seat `p`: winning the round and its points, or the points held. */
function ocPlayoutScore(x: OcState, p: number, round: number): number {
  const done = x.round > round || x.ph === OC_PH_OVER;
  if (done && x.last && x.last.roundWin >= 0) {
    if (x.last.roundWin === p) return 1 + Math.min(1, x.last.points / 150);
    // Someone else went out: what our hand cost them (and us) matters.
    return -Math.min(1, ocHandPoints(ocHandsBefore(x, p)) / 150) - 0.3;
  }
  return 0.25 * ocHeuristic({ ...x, who: p });
}

/** The hand `p` held when the round ended (the next round is already dealt by then). */
function ocHandsBefore(x: OcState, p: number): number[] {
  const h = (x as OcState & { endHands?: number[][] }).endHands;
  return h ? h[p] : x.hand[p];
}

/**
 * Perfect-information Monte Carlo: deal what the mover cannot see again `worlds` times, play
 * each legal move in each world and finish the round with the playout policy, keep the move that
 * did best. It never looks at the real hidden cards. `random` drives the re-deals.
 */
function ocPimcMove(s: OcState, worlds: number, random: () => number): number {
  const p = s.who;
  const all = ocLegalMoves(s);
  if (all.indexOf(OC_M_CALL + p) >= 0) return OC_M_CALL + p;
  // The candidates: every card that can be played (a Wild / Color Crush only naming the colour we
  // hold most), and keeping a drawn card. Drawing while holding a playable card never measured
  // better than playing it, and the extra candidates only add noise to the comparison.
  const col = ocBestColor(s, p, -1);
  const legal = all.filter((m) => m < OC_M_WILD || m === OC_M_WILD + col || m === OC_M_CRUSH + col || m === OC_M_PASS);
  if (legal.length === 0) return ocGreedyMove(s);
  if (legal.length === 1) return legal[0];
  const score: number[] = legal.map(() => 0);
  for (let w = 0; w < worlds; w += 1) {
    const det = ocDeterminize(s, p, random);
    for (let i = 0; i < legal.length; i += 1) {
      let x = ocPlayoutApply(det, legal[i]);
      for (let ply = 0; ply < OC_PLAYOUT_PLIES && x.ph !== OC_PH_OVER && x.round === s.round; ply += 1) x = ocPlayoutApply(x, ocPlayoutMove(x));
      score[i] += ocPlayoutScore(x, p, s.round);
    }
  }
  // The greedy choice starts ahead: the playouts must clearly prefer another move to switch.
  const g = legal.indexOf(ocGreedyMove(s));
  if (g >= 0) score[g] += OC_PIMC_PRIOR * worlds;
  let best = 0;
  for (let i = 1; i < legal.length; i += 1) if (score[i] > score[best]) best = i;
  return legal[best];
}

/** `ocApply`, keeping the hands as they were when a round ends (for the playout's score). */
function ocPlayoutApply(x: OcState, m: number): OcState {
  const round = x.round;
  const y = ocApply(x, m) as OcState & { endHands?: number[][] };
  if (y.round !== round) y.endHands = x.hand.map((h, q) => (q === x.who && y.last && y.last.k === "play" ? ocZeros(OC_CODES) : h));
  return y;
}

