function txRun(fn: () => Promise<void>): Promise<void> {
  txChain = txChain.then(fn).catch((error) => {
    world.log("OCHO error: " + txDescribe(error));
  });
  return txChain;
}

function txDescribe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

// --------------------------------------------------------------------------------- names --

function txCardName(c: number): string {
  if (c === OC_WILD) return "Wild";
  if (c === OC_CRUSH) return "Color Crush";
  const k = ocKindOf(c);
  const what = k === OC_SKIP ? "Skip" : k === OC_TURN ? "Turn" : k === OC_DRAW2 ? "Draw 2" : String(k + 1);
  return TX_COLOR_NAMES[ocColorOf(c)] + " " + what;
}

/** "a Red 7", "an 8", "a Wild". */
function txA(c: number): string {
  const name = txCardName(c);
  return (/^[AEIOU8]/.test(name) || /^(Red|Yellow|Blue|Green) (8|11)$/.test(name) ? "an " : "a ") + name;
}

function txCardId(c: number): string {
  txCopy += 1;
  return TX_CARD_IDS[c] + "#" + (100 + txCopy);
}

function txCount(n: number): string {
  return n + (n === 1 ? " card" : " cards");
}

function txSeatName(q: number): string {
  const id = txSeats[q];
  if (txPractice) return q === 0 ? "You" : "Bot " + q;
  const p = world.getPlayers().find((x) => x.seat === id);
  if (p && p.displayName) return p.displayName;
  return id.charAt(0).toUpperCase() + id.slice(1);
}

// --------------------------------------------------------------------------------- seats --

function txIsBotSeat(q: number): boolean {
  if (txPractice) return q !== 0 || txAutoplay;
  if (txGone[q]) return true;
  const id = txSeats[q];
  return world.getPlayers().some((p) => p.seat === id && p.isBot);
}

function txHumanSeat(q: number): boolean {
  return !txIsBotSeat(q);
}

/** The kernel seat a click or press came from (practice: anyone plays seat 0), or -1. */
function txSeatOf(seat: string | null, actor: string | null): number {
  if (txPractice) return 0;
  let id = seat;
  if (!id && actor) {
    const p = world.getPlayers().find((x) => x.peerId === actor);
    id = p ? p.seat : null;
  }
  return id ? txSeats.indexOf(id) : -1;
}

function txChooseSeats(): void {
  const occupied = TX_SEAT_ORDER.filter((seat) => world.getPlayers().some((p) => p.seat === seat));
  if (occupied.length >= 2) {
    txSeats = occupied;
    txPractice = false;
    return;
  }
  // Practice: the one person (or nobody) against three bots the script plays, round the far side of the table.
  const mine = occupied.length === 1 ? occupied[0] : "red";
  const at = TX_SEAT_ORDER.indexOf(mine);
  txSeats = [0, 2, 3, 4].map((d) => TX_SEAT_ORDER[(at + d) % TX_SEAT_ORDER.length]);
  txPractice = true;
}

// --------------------------------------------------------------------------------- geometry --

async function txLoadZones(): Promise<boolean> {
  txZones = {};
  for (const seat of txSeats) {
    const live = await world.getSeatZones(seat);
    // An unclaimed seat (practice, a preview) has no live zones: use the authored ones.
    const list = live.some((z) => z.zoneType === "hand") ? live : TX_FALLBACK_ZONES[seat] || live;
    const byName: { [name: string]: SeatZoneInfo } = {};
    for (const z of list) byName[z.zoneType === "hand" ? "Hand" : z.name] = z;
    txZones[seat] = byName;
    txRealHand[seat] = !txPractice && live.some((z) => z.zoneType === "hand");
  }
  txTableZones = {};
  let table = (await world.getSeatZones()).filter((z) => z.seat === null);
  if (!table.some((z) => z.name === "DiscardPile")) table = TX_FALLBACK_TABLE_ZONES;
  for (const z of table) txTableZones[z.name] = z;
  return txSeats.every((seat) => !!txZones[seat] && !!txZones[seat]["Hand"]);
}

/** A point in a zone's frame: local +x runs to the seat's left, local +z toward the middle of the table. */
function txLocal(zone: SeatZoneInfo, lx: number, lz: number, lift: number): Vec3 {
  const a = (zone.rotationY * Math.PI) / 180;
  return [zone.position[0] + lx * Math.cos(a) + lz * Math.sin(a), txSurface + 0.002 + lift, zone.position[2] - lx * Math.sin(a) + lz * Math.cos(a)];
}

/** The yaw that makes a card read upright for the seat that owns `zone`. */
function txZoneYaw(zone: SeatZoneInfo): number {
  return (((zone.rotationY + 180) % 360) + 360) % 360;
}

function txInZone(z: SeatZoneInfo, pos: Vec3, margin: number): boolean {
  const a = (z.rotationY * Math.PI) / 180;
  const dx = pos[0] - z.position[0];
  const dz = pos[2] - z.position[2];
  const lx = dx * Math.cos(a) - dz * Math.sin(a);
  const lz = dx * Math.sin(a) + dz * Math.cos(a);
  return Math.abs(lx) <= z.size[0] / 2 + margin && Math.abs(lz) <= z.size[2] / 2 + margin;
}

function txTableZone(name: string): SeatZoneInfo {
  const z = txTableZones[name];
  if (z) return z;
  const fallback = TX_FALLBACK_TABLE_ZONES.find((x) => x.name === name);
  return fallback || TX_FALLBACK_TABLE_ZONES[0];
}

// --------------------------------------------------------------------------------- entities --

/** Where the script spawns before moving a piece into place: open table, clear of every zone (the piles are stack zones). */
function txSpawnPoint(): Vec3 {
  return [-1.3, txSurface + 0.4, 0.6];
}

async function txDestroy(id: string): Promise<void> {
  const h = await world.getObjectById(id);
  if (h) h.destroy();
}

/** A locked loose card. `c` null: a face-down card whose face nobody may learn (it carries a stand-in id). */
async function txSpawnCard(c: number | null, pos: Vec3, yaw: number, faceDown: boolean, name: string): Promise<string | null> {
  const handle = (await world.spawnObject({
    kind: "card",
    presetId: "card-standard",
    name,
    position: txSpawnPoint(),
    rotation: [0, yaw, 0],
    metadata: { customDeck: TX_DECK_ART, cardId: c === null ? TX_CARD_IDS[0] : txCardId(c), standardPresetId: "card-standard" },
    tags: [TX_TAG]
  })) as CardObject | null;
  if (!handle) return null;
  handle.setPosition(pos);
  handle.setRotation([0, yaw, 0]);
  if (faceDown ? handle.faceUp !== false : handle.faceUp === false) handle.flip();
  handle.lock();
  return handle.id;
}

/** A locked pile of `n` cards (`faces` first = uppermost, or null for stand-in backs). One card is spawned as a card. */
async function txSpawnStack(faces: number[] | null, n: number, pos: Vec3, yaw: number, faceDown: boolean, name: string): Promise<string | null> {
  if (n <= 0) return null;
  if (n === 1) return txSpawnCard(faces ? faces[0] : null, pos, yaw, faceDown, name);
  const cards: { cardId: string; faceDown: boolean }[] = [];
  for (let i = 0; i < n; i += 1) cards.push({ cardId: faces ? txCardId(faces[i]) : TX_CARD_IDS[0] + "#" + (100 + i), faceDown });
  const handle = await world.spawnObject({
    kind: "deck",
    presetId: "deck-standard",
    name,
    position: txSpawnPoint(),
    rotation: [0, yaw, 0],
    metadata: { customDeck: TX_DECK_ART, cards, standardPresetId: "deck-standard" },
    tags: [TX_TAG]
  });
  if (!handle) return null;
  handle.setPosition([pos[0], pos[1] + (n * TX_CARD_T) / 2, pos[2]]);
  handle.setRotation([0, yaw, 0]);
  handle.lock();
  return handle.id;
}

/** Deal one card into a seat's real hand: a one-card pile, dealt with the platform's own deal (private to the seat). */
async function txDealToHand(seat: string, c: number): Promise<string | null> {
  const pile = (await world.spawnObject({
    kind: "deck",
    presetId: "deck-standard",
    name: "Dealing",
    position: txSpawnPoint(),
    metadata: { customDeck: TX_DECK_ART, cards: [{ cardId: txCardId(c), faceDown: true }], standardPresetId: "deck-standard" },
    tags: [TX_DEAL_TAG]
  })) as DeckObject | null;
  if (!pile) return null;
  let dealt: CardObject | null = null;
  try {
    dealt = await pile.dealTo({ seat });
  } catch (error) {
    dealt = null;
  }
  const left = await world.getObjectById(pile.id);
  if (left) left.destroy();
  return dealt ? dealt.id : null;
}

// --------------------------------------------------------------------------------- render --

/** Sort order in a row: by colour, then kind; Wild and Color Crush last. */
function txSortKey(c: number): number {
  return c;
}

async function txRenderHand(s: OcState, q: number): Promise<void> {
  const seat = txSeats[q];
  const real = !!txRealHand[seat];
  const want = s.hand[q].slice();
  const keep: TxEnt[] = [];
  for (const e of txHand[seat] || []) {
    if (want[e.c] > 0) {
      want[e.c] -= 1;
      keep.push(e);
    } else await txDestroy(e.id);
  }
  const showFaces = txPractice && q === 0;
  for (let c = 0; c < OC_CODES; c += 1) {
    for (let k = 0; k < want[c]; k += 1) {
      const id = real ? await txDealToHand(seat, c) : await txSpawnCard(showFaces ? c : null, txSpawnPoint(), 0, !showFaces, showFaces ? txCardName(c) : "Card");
      if (id) keep.push({ id, c });
    }
  }
  txHand[seat] = keep;
  if (real) return;
  // A row on the table (practice and previews): sorted, the seat's left first.
  const zone = txZones[seat] && txZones[seat]["Hand"];
  if (!zone) return;
  keep.sort((a, b) => txSortKey(a.c) - txSortKey(b.c));
  const n = keep.length;
  const step = n <= 1 ? 0 : Math.min(0.17, 1.4 / (n - 1));
  for (let i = 0; i < n; i += 1) {
    const h = await world.getObjectById(keep[i].id);
    if (!h) continue;
    h.unlock();
    h.setPosition(txLocal(zone, ((n - 1) * step) / 2 - i * step, 0, i * 0.0012));
    h.setRotation([0, txZoneYaw(zone), 0]);
    h.lock();
  }
}

async function txRenderPile(s: OcState): Promise<void> {
  // One face-up stack, newest card uppermost (the zone stacks whatever lands in it, so it is drawn whole).
  const key = s.pile.length + ":" + s.pile.slice(-3).join(",");
  if (txPileEnt && txPileEnt.key === key) return;
  if (txPileEnt) await txDestroy(txPileEnt.id);
  txPileEnt = null;
  const zone = txTableZone("DiscardPile");
  const faces = s.pile.slice().reverse();
  const id = await txSpawnStack(faces, faces.length, [zone.position[0], txSurface + 0.001, zone.position[2]], 0, false, "Play pile");
  if (id) txPileEnt = { id, key };
}

async function txRenderDraw(s: OcState): Promise<void> {
  const n = s.draw.length;
  if (txDrawEnt && txDrawEnt.n === n) return;
  if (txDrawEnt) await txDestroy(txDrawEnt.id);
  txDrawEnt = null;
  if (n <= 0) return;
  const zone = txTableZone("Deck");
  const id = await txSpawnStack(null, n, [zone.position[0], txSurface + 0.001, zone.position[2]], 0, true, "Draw pile");
  if (id) txDrawEnt = { id, n };
}

/** The active colour, written on both sides of the piles. */
function txRenderColor(s: OcState): void {
  const deck = txTableZone("Deck");
  const pile = txTableZone("DiscardPile");
  const x = (deck.position[0] + pile.position[0]) / 2;
  const z = deck.position[2];
  const text = TX_COLOR_NAMES[s.color].toUpperCase();
  const k = s.color + ":" + (s.ph === OC_PH_OVER ? "over" : "on");
  if (txHudCache["__color"] === k) return;
  txHudCache["__color"] = k;
  if (s.ph === OC_PH_OVER) {
    world.removeTextLabel("ocho-color-a");
    world.removeTextLabel("ocho-color-b");
    return;
  }
  world.setTextLabel({ id: "ocho-color-a", text, position: [x, txSurface + 0.005, z + 0.36], rotationY: 0, size: 0.09, color: "#ffffff", background: TX_COLOR_HEX[s.color] });
  world.setTextLabel({ id: "ocho-color-b", text, position: [x, txSurface + 0.005, z - 0.36], rotationY: 180, size: 0.09, color: "#ffffff", background: TX_COLOR_HEX[s.color] });
}

/** Make the table match the kernel state (renders run one at a time; each draws the newest state). */
function txRender(): Promise<void> {
  txRenderChain = txRenderChain.then(() => txRenderNow()).catch((error) => {
    world.log("OCHO render error: " + txDescribe(error));
  });
  return txRenderChain;
}

async function txRenderNow(): Promise<void> {
  const s = txState;
  if (!s) return;
  for (let q = 0; q < txSeats.length; q += 1) await txRenderHand(s, q);
  await txRenderPile(s);
  await txRenderDraw(s);
  txRenderColor(s);
  txRenderHud(s);
  txRenderHighlights(s);
}

// --------------------------------------------------------------------------------- HUD --

function txHudSet(key: string, value: UiValue, seat?: string, priv?: boolean): void {
  const k = (seat || "") + "|" + key + "|" + (priv ? "p" : "");
  if (k in txHudCache && txHudCache[k] === value) return;
  txHudCache[k] = value;
  if (seat) ui.set(key, value, seat, priv ? { private: true } : undefined);
  else ui.set(key, value);
}

function txDrawHud(): void {
  ui.show({
    id: "status",
    kind: "status",
    placement: { region: "upper" },
    theme: { icon: "playing_cards" },
    title: "{phase}",
    text: "{howToAll|}{seat.howTo|}",
    note: "{pileNote|}"
  });
  ui.show({
    id: "players",
    kind: "player-panel",
    counters: [
      { label: "Cards", value: "{seat.cards|0}", icon: "back_hand" },
      { label: "Score", value: "{seat.score|0}", icon: "emoji_events" }
    ]
  });
  ui.show({ id: "log", kind: "log", title: "Game log", placement: { region: "end" }, maxLines: 150 });
}

function txPhaseText(s: OcState): string {
  if (s.ph === OC_PH_OVER) return s.win === -2 ? "The game ends in a tie" : txSeatName(s.win) + " wins the game!";
  const upcard = s.pile[s.pile.length - 1];
  const match = upcard === OC_WILD || upcard === OC_CRUSH ? TX_COLOR_NAMES[s.color] : TX_COLOR_NAMES[s.color] + " or " + (ocKindOf(upcard) < 12 ? "any " + (ocKindOf(upcard) + 1) : "any " + txCardName(upcard).split(" ").slice(1).join(" "));
  return txSeatName(s.who) + (s.ph === OC_PH_DRAWN ? " drew a card" : " to play") + " - match " + match;
}

function txHowTo(s: OcState, q: number): string | null {
  if (s.ph === OC_PH_OVER) return null;
  if (s.exp[q]) return "You're down to one card - press OCHO! before someone catches you.";
  if (s.who !== q) return null;
  if (s.ph === OC_PH_DRAWN) return "You drew " + txA(s.drawn) + ". Play it now, or keep it and end your turn.";
  const legal = ocLegalMoves(s);
  const plays = legal.filter((m) => m < OC_M_DRAW);
  const where = txRealHand[txSeats[q]] ? "Click a card in your hand (or drag it onto the pile)" : "Click a card in your row";
  if (plays.length === 0) return legal.indexOf(OC_M_DRAW) >= 0 ? "Nothing matches. Draw a card: click the draw pile or press Draw." : "Nothing matches and there is nothing to draw: pass.";
  return where + " to play it, or draw from the pile. Outlined cards match.";
}

function txRenderHud(s: OcState): void {
  txHudSet("phase", txPhaseText(s));
  const turn = s.dir > 0 ? "clockwise" : "counter-clockwise";
  txHudSet("pileNote", "Active color: " + TX_COLOR_NAMES[s.color] + "  ·  Play goes " + turn + "  ·  Draw pile " + s.draw.length + "  ·  Round " + (s.round + (s.ph === OC_PH_OVER ? 0 : 1)) + ", first to " + s.target);
  const scores: Record<string, number> = {};
  for (let q = 0; q < txSeats.length; q += 1) {
    const seat = txSeats[q];
    txHudSet("cards", ocHandSize(s.hand[q]), seat);
    txHudSet("score", s.score[q], seat);
    scores[seat] = s.score[q];
    const how = txHumanSeat(q) ? txHowTo(s, q) : null;
    if (txPractice) {
      if (q === 0) txHudSet("howToAll", how);
    } else txHudSet("howTo", how, seat, true);
  }
  const sk = JSON.stringify(scores);
  if (txHudCache["__scores"] !== sk) {
    txHudCache["__scores"] = sk;
    world.setScores(scores);
  }
  if (s.ph === OC_PH_OVER) world.setTurn(null);
  else world.setTurn(txSeats[s.who]);
  txRenderMoves(s);
  txRenderOcho(s);
}

function txAudience(q: number): UiAudience {
  return txPractice ? { scope: "all" } : { scope: "seats", seats: [txSeats[q]] };
}

/** A HUD button for one move (a Wild / Color Crush is one button that asks for the colour). */
function txMoveButton(s: OcState, m: number): { id: string; label: string; icon: string; tone: UiTone } {
  if (m === OC_M_DRAW) return { id: "m" + m, label: "Draw a card", icon: "add_card", tone: "warning" };
  if (m === OC_M_PASS) return { id: "m" + m, label: s.ph === OC_PH_DRAWN ? "Keep it" : "Pass", icon: "skip_next", tone: "neutral" };
  if (m >= OC_M_WILD && m < OC_M_WILD + OC_COLORS) return { id: "w" + OC_WILD, label: "Play Wild", icon: "palette", tone: "accent" };
  if (m >= OC_M_CRUSH && m < OC_M_CRUSH + OC_COLORS) return { id: "w" + OC_CRUSH, label: "Play Color Crush", icon: "palette", tone: "accent" };
  return { id: "m" + m, label: "Play " + txCardName(m), icon: "playing_cards", tone: "accent" };
}

/** The mover's buttons: every legal move, while a person is to play. */
function txRenderMoves(s: OcState): void {
  const q = s.who;
  if (s.ph === OC_PH_OVER || !txHumanSeat(q) || txOver) {
    ui.hide(["ocho-moves", "ocho-color"]);
    return;
  }
  const seen: { [id: string]: boolean } = {};
  const buttons: { id: string; label: string; icon: string; tone: UiTone }[] = [];
  for (const m of ocLegalMoves(s)) {
    if (m >= OC_M_CALL) continue;
    const b = txMoveButton(s, m);
    if (seen[b.id]) continue;
    seen[b.id] = true;
    buttons.push(b);
  }
  ui.show({
    id: "ocho-moves",
    kind: "actions",
    placement: { region: "lower" },
    audience: txAudience(q),
    title: s.ph === OC_PH_DRAWN ? "You drew " + txA(s.drawn) : "Your move",
    actions: buttons.slice(0, 18)
  });
}

/** The OCHO call (for whoever sits on one uncalled card) and the catch buttons (for everyone else). */
function txRenderOcho(s: OcState): void {
  const exposed: number[] = [];
  for (let q = 0; q < txSeats.length; q += 1) if (s.exp[q]) exposed.push(q);
  const humans: number[] = [];
  for (let q = 0; q < txSeats.length; q += 1) if (txHumanSeat(q)) humans.push(q);
  const key = exposed.join(",") + "|" + humans.join(",") + "|" + (txOver ? 1 : 0);
  if (txHudCache["__ocho"] === key) return;
  txHudCache["__ocho"] = key;
  ui.hide(["ocho-call", "ocho-catch"]);
  for (const seat of TX_SEAT_ORDER) ui.hide(["ocho-call-" + seat, "ocho-catch-" + seat]);
  if (txOver || exposed.length === 0) return;
  for (const q of exposed) {
    if (!txHumanSeat(q)) continue;
    ui.show({
      id: "ocho-call-" + txSeats[q],
      kind: "actions",
      placement: { region: "center" },
      audience: txAudience(q),
      title: "One card left!",
      actions: [{ id: "call", label: "OCHO!", icon: "campaign", tone: "danger" }]
    });
  }
  // Everyone else may catch: a button per person watching, naming who can be caught.
  for (const watcher of humans) {
    const targets = exposed.filter((q) => q !== watcher);
    if (targets.length === 0 || (txPractice && watcher !== 0)) continue;
    ui.show({
      id: "ocho-catch-" + txSeats[watcher],
      kind: "actions",
      placement: { region: "lower-start" },
      audience: txAudience(watcher),
      title: "Didn't say OCHO!",
      actions: targets.map((q) => ({ id: "c" + q, label: "Catch " + txSeatName(q), icon: "front_hand", tone: "warning" as UiTone }))
    });
  }
}

/** Outline what the mover may play, privately; the draw pile when drawing is the only move. */
function txRenderHighlights(s: OcState): void {
  const ids: string[] = [];
  const q = s.who;
  if (s.ph !== OC_PH_OVER && txHumanSeat(q) && !txOver) {
    const seat = txSeats[q];
    const legal = ocLegalMoves(s);
    for (const e of txHand[seat] || []) {
      const ok = s.ph === OC_PH_DRAWN ? e.c === s.drawn : e.c === OC_WILD ? legal.indexOf(OC_M_WILD) >= 0 : e.c === OC_CRUSH ? legal.indexOf(OC_M_CRUSH) >= 0 : legal.indexOf(e.c) >= 0;
      if (ok) ids.push(e.id);
    }
    if (ids.length === 0 && s.ph === OC_PH_PLAY && txDrawEnt) ids.push(txDrawEnt.id);
  }
  const key = (txPractice ? "all" : String(q)) + ":" + ids.join(",");
  if (key === txLastHighlight) return;
  txLastHighlight = key;
  world.clearHighlights();
  if (ids.length > 0) world.setHighlight(ids, "playable", txPractice ? undefined : { seats: [txSeats[q]] });
}

// --------------------------------------------------------------------------------- log --

function txLogMove(before: OcState, s: OcState): void {
  const e = s.last;
  if (!e) return;
  const who = txSeatName(e.p);
  const seat = txSeats[e.p];
  const lines: string[] = [];
  switch (e.k) {
    case "play": {
      let t = who + (e.drawPlay ? " draws and plays " : " plays ") + txA(e.c);
      if (e.col >= 0) t += " and names " + TX_COLOR_NAMES[e.col];
      if (e.roundWin < 0) {
        const k = ocKindOf(e.c);
        if (k === OC_SKIP || (k === OC_TURN && txSeats.length === 2)) t += ": " + txSeatName(e.skipped) + " is skipped";
        else if (k === OC_TURN) t += ": play now goes " + (s.dir > 0 ? "clockwise" : "counter-clockwise");
      }
      lines.push(t + ".");
      if (e.penSeat >= 0) {
        const pw = txSeatName(e.penSeat);
        if (e.esc >= 0) lines.push(pw + " draws " + txCount(e.penDrew) + ", then an 8 - OCHO Escape! " + txCardName(e.esc) + " goes on the pile and " + TX_COLOR_NAMES[ocColorOf(e.esc)] + " is the color.");
        else lines.push(pw + " draws " + txCount(e.penDrew) + " and loses the turn.");
      }
      break;
    }
    case "draw":
      lines.push(who + " draws a card" + (s.ph === OC_PH_DRAWN ? "." : " and can't play it."));
      break;
    case "pass":
      lines.push(who + (before.ph === OC_PH_DRAWN ? " keeps the drawn card." : " passes."));
      break;
    case "call":
      lines.push(who + ": OCHO!");
      break;
    case "catch":
      lines.push(who + " was caught without saying OCHO and draws " + txCount(e.penDrew) + ".");
      break;
    case "void":
      lines.push("The round has gone on too long: no points, and the cards are dealt again.");
      break;
    default:
      return;
  }
  if (e.reshuffled) lines.push("The draw pile ran out: the play pile is shuffled into a new one.");
  if (e.roundWin >= 0) lines.push(txSeatName(e.roundWin) + " is out of cards and wins round " + s.round + " for " + e.points + " points.");
  for (const t of lines) ui.log(t, { seat });
}

// --------------------------------------------------------------------------------- moves --

/** Apply one move at once (from a person, a bot or the OCHO race), record it, log it, start what follows. */
function txApply(m: number): void {
  if (!txState) return;
  const before = txState;
  txState = kernel.apply(txState, m);
  txLogMove(before, txState);
  if (txRecording) {
    try {
      match.move(m);
    } catch (error) {
      txRecording = false;
      world.log("OCHO: the match stopped recording (" + txDescribe(error) + ").");
    }
  }
  txAfterApply(before, txState);
}

/** Someone was just left on one uncalled card: a bot says OCHO (unless it forgets), and the bots watching may catch. */
function txAfterApply(before: OcState, s: OcState): void {
  if (s.ph === OC_PH_OVER || s.round !== before.round) return;
  for (let q = 0; q < txSeats.length; q += 1) {
    if (!s.exp[q] || before.exp[q]) continue;
    if (txIsBotSeat(q)) {
      const level = TX_BOT_OCHO[txBotOf(q).difficulty || "normal"] || TX_BOT_OCHO["normal"];
      if (Math.random() >= level.forget) {
        txApply(OC_M_CALL + q);
        continue;
      }
    }
    txWatchCatch(q, s.ply);
  }
}

/** Each bot at the table (other than `q`) may catch `q` after a moment, if the chance is still open. */
function txWatchCatch(q: number, ply: number): void {
  for (let b = 0; b < txSeats.length; b += 1) {
    if (b === q || !txIsBotSeat(b)) continue;
    if (txPractice && b === 0) continue;
    const level = TX_BOT_OCHO[txBotOf(b).difficulty || "normal"] || TX_BOT_OCHO["normal"];
    if (Math.random() >= level.catchChance) continue;
    const delay = level.min + Math.random() * (level.max - level.min);
    const round = txState ? txState.round : -1;
    void (async () => {
      await world.wait(delay);
      const s = txState;
      if (!s || txOver || s.round !== round || !s.exp[q] || s.ply < ply) return;
      ui.log(txSeatName(b) + " catches " + txSeatName(q) + "!", { seat: txSeats[b] });
      txApply(OC_M_CATCH + q);
      await txRender();
      void txRun(() => txAdvance());
    })();
  }
}

type TxChooser = (s: OcState, difficulty: string | null) => number;

const TX_CHOOSERS: { [botId: string]: TxChooser } = {
  casual: (s) => ocGreedyMove(s),
  "card-shark": (s, difficulty) => ocPimcMove(s, TX_SHARK_WORLDS[difficulty || "normal"] || 24, Math.random)
};

function txBotOf(q: number): { chooser: TxChooser; difficulty: string | null } {
  if (txPractice) return { chooser: TX_CHOOSERS["card-shark"], difficulty: "normal" };
  if (txGone[q]) return { chooser: TX_CHOOSERS["casual"], difficulty: "normal" };
  const p = world.getPlayers().find((x) => x.seat === txSeats[q] && x.isBot);
  const chooser = p && p.botId && TX_CHOOSERS[p.botId] ? TX_CHOOSERS[p.botId] : TX_CHOOSERS["card-shark"];
  return { chooser, difficulty: p ? p.difficultyId : null };
}

/** A bot's move, never an OCHO call / catch (those run on their own clock), always legal. */
function txBotMove(s: OcState, q: number): number {
  const bot = txBotOf(q);
  const view: OcState = { ...s, exp: s.exp.map(() => 0) };
  let m = -1;
  try {
    m = bot.chooser(view, bot.difficulty);
  } catch (error) {
    m = ocGreedyMove(view);
  }
  if (ocLegalMoves(s).indexOf(m) < 0 || m >= OC_M_CALL) m = ocGreedyMove(view);
  return m;
}

/** Play everything that does not wait for a person: the bots' moves. Stops when a person must move or the game ends. */
async function txAdvance(signal?: BotAbortSignal): Promise<void> {
  for (let guard = 0; guard < 4000; guard += 1) {
    const s = txState;
    if (!s || s.ph === OC_PH_OVER || txOver) break;
    if (txRoundShown >= 0) break;
    const q = s.who;
    if (!txIsBotSeat(q) || txColorAsk) break;
    if (signal && signal.aborted) return;
    // Someone can still say OCHO or be caught: give people time before the bot's move closes the chance.
    if (s.exp.some((x) => x === 1) && txWindowPly !== s.ply) {
      txWindowPly = s.ply;
      await world.wait(TX_OCHO_WINDOW);
      continue;
    }
    const m = txBotMove(s, q);
    if (txState !== s) continue;
    const round = s.round;
    txApply(m);
    await txRender();
    if (txState && txState.round !== round) {
      await txRoundOver();
      continue;
    }
    if (txState && txState.ph !== OC_PH_OVER && txIsBotSeat(txState.who)) await world.wait(TX_BOT_PACE);
  }
  await txAfterMoves();
}

async function txAfterMoves(): Promise<void> {
  if (!txState) return;
  await txRender();
  if (txState.ph === OC_PH_OVER && !txOver) await txGameOver();
}

/** A person's move: check it is theirs and legal, play it, then everything that follows. */
async function txHumanMove(q: number, m: number): Promise<void> {
  const s = txState;
  if (!s || txOver || s.ph === OC_PH_OVER || txRoundShown >= 0) return;
  if (q !== s.who || txIsBotSeat(q)) {
    txHint(q, "It's " + txSeatName(s.who) + "'s turn.");
    return;
  }
  if (ocLegalMoves(s).indexOf(m) < 0) {
    txHint(q, s.ph === OC_PH_DRAWN ? "After drawing you may only play the card you drew, or keep it." : "That card doesn't match: " + txPhaseText(s).split(" - ")[1] + ".");
    return;
  }
  txHumanMoved = true;
  txColorAsk = null;
  ui.hide("ocho-color");
  const round = s.round;
  txApply(m);
  await txRender();
  if (txState && txState.round !== round) await txRoundOver();
  if (txState && txState.ph !== OC_PH_OVER && txIsBotSeat(txState.who)) await world.wait(TX_BOT_PACE * 0.6);
  await txAdvance();
}

function txHint(q: number, text: string): void {
  if (q < 0) return;
  ui.toast(text, { tone: "warning", icon: "info", to: txAudience(q) });
}

/** Seat `q` picked card code `c` (clicked, dragged onto the pile or pressed): play it, asking for a colour if it needs one. */
function txOfferPlay(q: number, c: number): void {
  const s = txState;
  if (!s || s.ph === OC_PH_OVER || txOver) return;
  if (s.who !== q) {
    txHint(q, "It's " + txSeatName(s.who) + "'s turn.");
    return;
  }
  if (s.ph === OC_PH_DRAWN && c !== s.drawn) {
    txHint(q, "After drawing you may only play the card you drew (" + txCardName(s.drawn) + "), or keep it.");
    return;
  }
  if (c === OC_WILD || c === OC_CRUSH) {
    txColorAsk = { q, c };
    ui.show({
      id: "ocho-color",
      kind: "prompt",
      audience: txAudience(q),
      title: c === OC_WILD ? "Wild: name the color" : "Color Crush: name the color",
      body: c === OC_CRUSH ? "The next player draws up to four cards - unless an 8 turns up (OCHO Escape)." : "The next player must match it.",
      actions: [0, 1, 2, 3].map((k) => ({ id: "k" + k, label: TX_COLOR_NAMES[k], icon: TX_COLOR_ICONS[k], color: TX_COLOR_HEX[k] })).concat([{ id: "cancel", label: "Cancel", icon: "close", color: "#888888" }]),
      dismissible: true,
      timing: { until: "action" }
    });
    return;
  }
  if (!ocCanPlay(s, c)) {
    txHint(q, txA(c) + " doesn't match: " + txPhaseText(s).split(" - ")[1] + ".");
    return;
  }
  void txRun(() => txHumanMove(q, c));
}

// --------------------------------------------------------------------------------- rounds and game --

/** Show the round that just ended, then the next deal. */
async function txRoundOver(): Promise<void> {
  const s = txState;
  if (!s) return;
  const e = s.last;
  if (s.ph === OC_PH_OVER) return;
  txRoundShown = s.round;
  if (e && e.roundWin >= 0) {
    const headline = txSeatName(e.roundWin) + " wins round " + s.round + " (+" + e.points + ")";
    ui.show({
      id: "ocho-round",
      kind: "result",
      headline,
      lines: txSeats.map((seat, q) => txSeatName(q) + ": " + s.score[q] + " points").concat(["Next round in a few seconds - first to " + s.target + " wins."])
    });
    ui.toast(headline, { tone: "success", icon: "emoji_events", seconds: 5 });
  }
  await world.wait(TX_ROUND_PAUSE);
  ui.hide("ocho-round");
  txRoundShown = -1;
  if (txState) {
    ui.log("Round " + (txState.round + 1) + ": " + txSeatName(txState.starter) + " goes first. The starting card is " + txA(txState.pile[txState.pile.length - 1]) + ".", { tone: "info" });
    await txRender();
  }
}

async function txClearTable(): Promise<void> {
  world.clearHighlights();
  txLastHighlight = "";
  ui.hide(["ocho-moves", "ocho-color", "ocho-result", "ocho-round", "ocho-game"]);
  for (const seat of TX_SEAT_ORDER) ui.hide(["ocho-call-" + seat, "ocho-catch-" + seat]);
  // In the Scripted variant every card on the table is the script's: the pack's own deck, cards dealt into hands, leftovers.
  for (const kind of ["card", "deck"] as const) for (const h of await world.getAllObjects({ kind })) h.destroy();
  for (const h of await world.getAllObjects({ tag: TX_TAG })) h.destroy();
  for (const seat of Object.keys(txHand)) delete txHand[seat];
  for (const k of Object.keys(txGone)) delete txGone[Number(k)];
  for (const k of Object.keys(txHudCache)) delete txHudCache[k];
  txPileEnt = null;
  txDrawEnt = null;
  txColorAsk = null;
  txRoundShown = -1;
  txWindowPly = -1;
}

async function txStartMatch(setup: OcSetup): Promise<void> {
  txRecording = false;
  if (typeof match === "undefined") return;
  const running = match.current();
  if (running && (running.status === "live" || running.status === "opening")) {
    try {
      await match.abort("new game");
    } catch (error) {
      world.log("OCHO: could not stop the previous match (" + txDescribe(error) + ").");
    }
  }
  if (txPractice) return;
  try {
    const info = await (match.start as unknown as TxMatchStart)({ kernel, setup, seats: txSeats });
    txRecording = !!info && info.status === "live";
  } catch (error) {
    world.log("OCHO: this game is not recorded as a match (" + txDescribe(error) + ").");
  }
}

async function txNewGame(): Promise<void> {
  txStarting = true;
  try {
    txOver = false;
    txHumanMoved = false;
    txChooseSeats();
    txDrawHud();
    if (!(await txLoadZones())) {
      txHudSet("phase", "OCHO cannot start");
      txHudSet("howToAll", "The table has no hand zones for these seats.");
      return;
    }
    txHudSet("phase", "Dealing a new game");
    await txClearTable();
    const setup: OcSetup = { seed: Math.floor(Math.random() * 2147483647), first: Math.floor(Math.random() * txSeats.length), target: OC_TARGET };
    txSetup = setup;
    await txStartMatch(setup);
    txState = kernel.initial(txSeats, setup);
    world.setGameOver(null);
    const names = txSeats.map((_, q) => txSeatName(q)).join(", ");
    const intro = "New game of OCHO: " + names + ". First to " + setup.target + " points. " + txSeatName(txState.starter) + " goes first." + (txPractice ? " Practice: you play against three bots." : "");
    ui.log(intro, { tone: "info" });
    ui.log("The starting card is " + txA(txState.pile[0]) + ".", { tone: "info" });
    txShowGameControls();
    ui.toast(intro, { tone: "info", icon: "playing_cards", seconds: 6 });
    await txRender();
    await txAdvance();
  } finally {
    txStarting = false;
  }
}

/** After a reload: rebuild the game from the running match (setup + recorded moves). */
async function txResume(): Promise<boolean> {
  if (typeof match === "undefined") return false;
  const info = match.current();
  if (!info || info.status !== "live") return false;
  const setup = match.setup() as OcSetup | undefined;
  if (!setup || typeof setup.seed !== "number") return false;
  try {
    const again = await (match.start as unknown as TxMatchStart)({ kernel });
    if (!again || again.id !== info.id) return false;
  } catch (error) {
    return false;
  }
  txSeats = info.participants.map((p) => p.seat);
  txPractice = false;
  if (!(await txLoadZones())) return false;
  txDrawHud();
  await txClearTable();
  txSetup = setup;
  let s = kernel.initial(txSeats, setup);
  for (const m of match.moves()) s = kernel.apply(s, m as number);
  txState = s;
  txRecording = true;
  txHumanMoved = true;
  ui.log("The running game was picked back up (" + match.moves().length + " moves).", { tone: "info" });
  await txRender();
  await txAdvance();
  return true;
}

/** Practice controls: a new deal at any time, and a bot for the person's seat. */
function txShowGameControls(): void {
  if (!txPractice) {
    ui.hide("ocho-game");
    return;
  }
  ui.show({
    id: "ocho-game",
    kind: "actions",
    placement: { region: "lower-end", devices: { phone: { menu: true } } },
    actions: [
      { id: "new", label: "New game", icon: "replay" },
      { id: "auto", label: txAutoplay ? "I'll play my cards" : "Let a bot play my cards", icon: txAutoplay ? "person" : "smart_toy" }
    ]
  });
}

async function txGameOver(): Promise<void> {
  const s = txState;
  if (!s || s.ph !== OC_PH_OVER) return;
  txOver = true;
  world.clearHighlights();
  txLastHighlight = "";
  ui.hide(["ocho-moves", "ocho-color", "ocho-round"]);
  const ranks = ocRanks(s);
  const leaders: string[] = [];
  for (let q = 0; q < txSeats.length; q += 1) if (ranks[q] === 1) leaders.push(txSeats[q]);
  const headline = leaders.length === 1 ? txSeatName(txSeats.indexOf(leaders[0])) + " wins the game with " + s.score[txSeats.indexOf(leaders[0])] + " points!" : "The game ends in a tie for first place.";
  const scores: Record<string, number> = {};
  const rankMap: Record<string, number> = {};
  for (let q = 0; q < txSeats.length; q += 1) {
    scores[txSeats[q]] = s.score[q];
    rankMap[txSeats[q]] = ranks[q];
  }
  const order = txSeats.map((_, q) => q).sort((a, b) => ranks[a] - ranks[b]);
  ui.show({
    id: "ocho-result",
    kind: "result",
    headline,
    lines: order.map((q) => ranks[q] + ". " + txSeatName(q) + ": " + s.score[q] + " points")
  });
  world.setGameOver(leaders.length === 1 ? { winner: leaders[0] } : { winners: leaders });
  ui.log(headline, { tone: "success" });
  ui.toast(headline, { tone: "success", icon: "emoji_events", seconds: 8 });
  ui.show({
    id: "ocho-game",
    kind: "actions",
    placement: { region: "lower-end" },
    actions: [{ id: "new", label: "New game", icon: "replay" }]
  });
  if (txRecording) {
    txRecording = false;
    match.end({ ranks: rankMap }, { reason: "points", scores }).catch((error) => {
      world.log("OCHO: the match result was not accepted (" + txDescribe(error) + ").");
    });
  }
}

// --------------------------------------------------------------------------------- events --

/** What one of the script's entities is: a hand card, the draw pile or the play pile. */
function txFind(id: string): { kind: string; q: number; c: number } | null {
  for (let q = 0; q < txSeats.length; q += 1) {
    for (const e of txHand[txSeats[q]] || []) if (e.id === id) return { kind: "hand", q, c: e.c };
  }
  if (txDrawEnt && txDrawEnt.id === id) return { kind: "draw", q: -1, c: -1 };
  if (txPileEnt && txPileEnt.id === id) return { kind: "pile", q: -1, c: -1 };
  return null;
}

globalEvents.onObjectClicked.add((object, context) => {
  const s = txState;
  if (!s || txOver) return;
  const what = txFind(object.id);
  if (!what) return;
  const q = txSeatOf(context.seat, context.actor);
  if (q < 0) return;
  if (what.kind === "draw") {
    if (s.who !== q) txHint(q, "It's " + txSeatName(s.who) + "'s turn.");
    else if (ocLegalMoves(s).indexOf(OC_M_DRAW) >= 0) void txRun(() => txHumanMove(q, OC_M_DRAW));
    else if (s.ph === OC_PH_DRAWN) txHint(q, "You've drawn already: play the card you drew, or keep it.");
    return;
  }
  if (what.kind === "hand" && what.q === q) txOfferPlay(q, what.c);
});

/** A hand card dragged out of the hand: onto the play pile it is played, anywhere else it goes back. */
globalEvents.onObjectDropped.add((object, context) => {
  void txRun(async () => {
    const s = txState;
    if (!s) return;
    const what = txFind(object.id);
    if (!what || what.kind !== "hand") return;
    const seat = txSeats[what.q];
    const hand = txZones[seat] && txZones[seat]["Hand"];
    if (hand && txInZone(hand, object.position, 0.02)) return;
    // The script's own moves (dealing, laying out a row) are not a person's drag.
    if (context.actor === "Script" || context.actor === "Host" || context.actor === "System") return;
    const q = txSeatOf(null, context.actor);
    // The card goes back into the hand either way (re-dealt on the redraw).
    txHand[seat] = (txHand[seat] || []).filter((e) => e.id !== object.id);
    await txDestroy(object.id);
    await txRender();
    if (q === what.q && txInZone(txTableZone("DiscardPile"), object.position, 0.3)) txOfferPlay(q, what.c);
  });
});

ui.onAction.add((event) => {
  const s = txState;
  if (!s) return;
  if (event.widgetId === "ocho-game" && event.actionId === "new") {
    if (!txOver && !txPractice) return;
    void txRun(() => txNewGame());
    return;
  }
  if (event.widgetId === "ocho-game" && event.actionId === "auto" && txPractice) {
    txAutoplay = !txAutoplay;
    txShowGameControls();
    if (txAutoplay) {
      ui.hide("ocho-color");
      txColorAsk = null;
    }
    void txRun(async () => {
      await txRender();
      await txAdvance();
    });
    return;
  }
  const q = txSeatOf(event.seat, event.peerId);
  // The OCHO race runs at once, outside the move queue: whoever presses first wins it.
  if (event.widgetId.indexOf("ocho-call-") === 0) {
    const owner = txSeats.indexOf(event.widgetId.slice("ocho-call-".length));
    if (owner < 0 || (owner !== q && !txPractice) || !s.exp[owner] || txOver) return;
    txApply(OC_M_CALL + owner);
    void txRender();
    void txRun(() => txAdvance());
    return;
  }
  if (event.widgetId.indexOf("ocho-catch-") === 0) {
    const target = Number((event.actionId || "").slice(1));
    if (!(target >= 0) || target === q || !s.exp[target] || txOver) return;
    ui.log(txSeatName(q) + " catches " + txSeatName(target) + "!", { seat: txSeats[q] });
    txApply(OC_M_CATCH + target);
    void txRender();
    void txRun(() => txAdvance());
    return;
  }
  if (event.widgetId === "ocho-color") {
    const ask = txColorAsk;
    ui.hide("ocho-color");
    txColorAsk = null;
    if (!ask || !event.actionId || event.actionId === "cancel" || event.dismissed) {
      void txRun(() => txAdvance());
      return;
    }
    const k = Number(event.actionId.slice(1));
    if (!(k >= 0 && k < OC_COLORS)) return;
    const m = (ask.c === OC_WILD ? OC_M_WILD : OC_M_CRUSH) + k;
    void txRun(() => txHumanMove(ask.q, m));
    return;
  }
  if (event.widgetId === "ocho-moves") {
    const id = event.actionId || "";
    if (id.charAt(0) === "w") {
      txOfferPlay(q, Number(id.slice(1)));
      return;
    }
    const m = Number(id.slice(1));
    if (!isFinite(m)) return;
    if (m < OC_M_DRAW) txOfferPlay(q, m);
    else void txRun(() => txHumanMove(q, m));
  }
});

/** People sitting down or bots joining before anyone has moved restart the deal with everyone in it. */
function txSeatsChanged(): void {
  if (txHumanMoved || txStarting || txRestartQueued) return;
  txRestartQueued = true;
  void txRun(async () => {
    await world.wait(1.5);
    txRestartQueued = false;
    if (txHumanMoved) return;
    const occupied = TX_SEAT_ORDER.filter((seat) => world.getPlayers().some((p) => p.seat === seat));
    const now = occupied.length >= 2 ? occupied.join(",") : "practice";
    const was = txPractice ? "practice" : txSeats.join(",");
    if (now !== was) await txNewGame();
  });
}

globalEvents.onSeatChanged.add(() => txSeatsChanged());
globalEvents.onPlayerJoined.add(() => txSeatsChanged());
globalEvents.onPlayerLeft.add(() => txSeatsChanged());

/**
 * The script rides on the pack's button (in the Scripted variant it replaces the Standard variant's deal script): pressing
 * it starts a new game once this one is over, or at any time in practice.
 */
if (refObject.kind === "button") {
  (refObject as unknown as ButtonObject).onPressed.add(() => {
    if (!txOver && !txPractice && txState) {
      ui.toast("The game is still on. The button starts a new game once someone reaches " + (txState.target || OC_TARGET) + " points.", { tone: "info", icon: "info" });
      return;
    }
    void txRun(() => txNewGame());
  });
}

function txBotTurn(ctx: BotTurnContext): Promise<void> {
  return txRun(() => txAdvance(ctx.signal));
}

// One literal registration per bot: the editor reads the handler ids out of these calls.
bots.register({ id: "casual", onTurn: (ctx) => txBotTurn(ctx) });
bots.register({ id: "card-shark", onTurn: (ctx) => txBotTurn(ctx) });

if (typeof match !== "undefined") {
  match.onForfeit.add((participant) => {
    void txRun(async () => {
      const s = txState;
      if (!s || s.ph === OC_PH_OVER) return;
      const q = txSeats.indexOf(participant.seat);
      if (q < 0) return;
      ui.log(txSeatName(q) + " forfeits.", { tone: "warning" });
      if (txSeats.length === 2) {
        // The platform records the forfeit; the board just shows it.
        txRecording = false;
        const score = s.score.slice();
        score[1 - q] = Math.max(score[1 - q], score[q] + 1);
        txState = { ...s, ph: OC_PH_OVER, win: 1 - q, score };
        await txAfterMoves();
        return;
      }
      ui.log("The table plays " + txSeatName(q) + "'s cards from now on.", { tone: "info" });
      txGone[q] = true;
      await txAdvance();
    });
  });
  match.onTakeback.add(() => {
    void txRun(async () => {
      if (!txSetup) return;
      let s = kernel.initial(txSeats, txSetup);
      for (const m of match.moves()) s = kernel.apply(s, m as number);
      txState = s;
      txOver = false;
      txColorAsk = null;
      ui.hide("ocho-color");
      await txRender();
      await txAdvance();
    });
  });
}

void txRun(async () => {
  const variant = world.getVariant();
  if (variant.id !== null && !variant.rulesEnforced) return;
  if (await txResume()) return;
  await world.wait(0.5);
  await txNewGame();
});

