        return "Wild";
    if (c === OC_CRUSH)
        return "Color Crush";
    const k = ocKindOf(c);
    const what = k === OC_SKIP ? "Skip" : k === OC_TURN ? "Turn" : k === OC_DRAW2 ? "Draw 2" : String(k + 1);
    return TX_COLOR_NAMES[ocColorOf(c)] + " " + what;
}
/** "a Red 7", "an 8", "a Wild". */
function txA(c) {
    const name = txCardName(c);
