// --------------------------------------------------------------------------------- HUD --
function txHudSet(key, value, seat, priv) {
    const k = (seat || "") + "|" + key + "|" + (priv ? "p" : "");
    if (k in txHudCache && txHudCache[k] === value)
        return;
    txHudCache[k] = value;
