        ui.set(key, value, seat, priv ? { private: true } : undefined);
    else
        ui.set(key, value);
}
function txDrawHud() {
    ui.show({
        id: "status",
        kind: "status",
        placement: { region: "upper" },
        theme: { icon: "playing_cards" },
        title: "{phase}",
        text: "{howToAll|}{seat.howTo|}",
