function txPhaseText(s) {
    if (s.ph === OC_PH_OVER)
        return s.win === -2 ? "The game ends in a tie" : txSeatName(s.win) + " wins the game!";
    const upcard = s.pile[s.pile.length - 1];
    const match = upcard === OC_WILD || upcard === OC_CRUSH ? TX_COLOR_NAMES[s.color] : TX_COLOR_NAMES[s.color] + " or " + (ocKindOf(upcard) < 12 ? "any " + (ocKindOf(upcard) + 1) : "any " + txCardName(upcard).split(" ").slice(1).join(" "));
    return txSeatName(s.who) + (s.ph === OC_PH_DRAWN ? " drew a card" : " to play") + " - match " + match;
}
function txHowTo(s, q) {
    if (s.ph === OC_PH_OVER)
        return null;
    if (s.exp[q])
        return "You're down to one card - press OCHO! before someone catches you.";
    if (s.who !== q)
        return null;
    if (s.ph === OC_PH_DRAWN)
        return "You drew " + txA(s.drawn) + ". Play it now, or keep it and end your turn.";
    const legal = ocLegalMoves(s);
    const plays = legal.filter((m) => m < OC_M_DRAW);
    const where = txRealHand[txSeats[q]] ? "Click a card in your hand (or drag it onto the pile)" : "Click a card in your row";
    if (plays.length === 0)
        return legal.indexOf(OC_M_DRAW) >= 0 ? "Nothing matches. Draw a card: click the draw pile or press Draw." : "Nothing matches and there is nothing to draw: pass.";
    return where + " to play it, or draw from the pile. Outlined cards match.";
}
function txRenderHud(s) {
    txHudSet("phase", txPhaseText(s));
    const turn = s.dir > 0 ? "clockwise" : "counter-clockwise";
    txHudSet("pileNote", "Active color: " + TX_COLOR_NAMES[s.color] + "  ·  Play goes " + turn + "  ·  Draw pile " + s.draw.length + "  ·  Round " + (s.round + (s.ph === OC_PH_OVER ? 0 : 1)) + ", first to " + s.target);
    const scores = {};
    for (let q = 0; q < txSeats.length; q += 1) {
        const seat = txSeats[q];
        txHudSet("cards", ocHandSize(s.hand[q]), seat);
        txHudSet("score", s.score[q], seat);
        scores[seat] = s.score[q];
        const how = txHumanSeat(q) ? txHowTo(s, q) : null;
        if (txPractice) {
            if (q === 0)
                txHudSet("howToAll", how);
        }
        else
            txHudSet("howTo", how, seat, true);
    }
    const sk = JSON.stringify(scores);
    if (txHudCache["__scores"] !== sk) {
        txHudCache["__scores"] = sk;
        world.setScores(scores);
    }
    if (s.ph === OC_PH_OVER)
        world.setTurn(null);
    else
        world.setTurn(txSeats[s.who]);
    txRenderMoves(s);
    txRenderOcho(s);
}
function txAudience(q) {
    return txPractice ? { scope: "all" } : { scope: "seats", seats: [txSeats[q]] };
}
/** A HUD button for one move (a Wild / Color Crush is one button that asks for the colour). */
function txMoveButton(s, m) {
    if (m === OC_M_DRAW)
        return { id: "m" + m, label: "Draw a card", icon: "add_card", tone: "warning" };
    if (m === OC_M_PASS)
        return { id: "m" + m, label: s.ph === OC_PH_DRAWN ? "Keep it" : "Pass", icon: "skip_next", tone: "neutral" };
    if (m >= OC_M_WILD && m < OC_M_WILD + OC_COLORS)
        return { id: "w" + OC_WILD, label: "Play Wild", icon: "palette", tone: "accent" };
    if (m >= OC_M_CRUSH && m < OC_M_CRUSH + OC_COLORS)
        return { id: "w" + OC_CRUSH, label: "Play Color Crush", icon: "palette", tone: "accent" };
