// One literal registration per bot: the editor reads the handler ids out of these calls.
bots.register({ id: "casual", onTurn: (ctx) => txBotTurn(ctx) });
bots.register({ id: "card-shark", onTurn: (ctx) => txBotTurn(ctx) });
if (typeof match !== "undefined") {
    match.onForfeit.add((participant) => {
        void txRun(async () => {
